// Result-independent sections of the paper (related work, data, method, setup).
// Anything that quotes a tuned setting reads it from facts.js.

const L = require("./lib");
const { para, bullets } = L;
const A = L.AlignmentType;

const P = (t, o) => para(t, { size: 19, line: 235, after: 70, ...o });

const relatedWork = (F) => [
  P("***A. Graph Neural Networks for Recommendation.*** Graph recommenders treat the interaction matrix as a bipartite or heterogeneous graph and learn embeddings by propagating along its edges. LightGCN [5] showed that feature transformation and non-linearities could be removed from graph convolution without hurting accuracy, and we use it as the strongest graph baseline. SASRec [12] is the usual sequential baseline on Amazon data: self-attention over the user's ordered history. HGT [1] generalises graph attention to graphs with several node and edge types through type-specific projections and relation-aware attention, which is what lets one encoder reason over users, products, reviews, brands and categories without forcing a shared feature space."),
  P("***B. Semantic Review Representations.*** Review text is an under-used signal in collaborative filtering. Sentence-BERT [2] fine-tunes a BERT encoder with a siamese objective so that cosine similarity between sentence embeddings tracks semantic similarity, avoiding the quadratic cost of cross-encoding every pair. We use the compact all-MiniLM-L6-v2 variant to attach a fixed-length vector to every review node."),
  P("***C. Shilling Attacks and Trust.*** Coordinated review campaigns are well documented, and robust graph recommenders have been proposed against them: Anti-FakeU [7] builds a user–user graph and a GNN detector to identify fake users, and Trust-GRS [8] estimates, without prior knowledge of the attack, the probability that each piece of data is fake and uses it to make neighbourhood aggregation and contrastive learning trustworthy. Heterogeneous graph transformers have also been applied to review fraud directly, as in FAHGT [9]. Our setting differs in that trust is not the model's goal but one input to a recommender that also has to explain itself, and we ask a narrower question: which unsupervised signal is a safe source of trust. CoLA [3], a contrastive anomaly detector that scores a node by how well its attributes can be predicted from its neighbourhood, was our first choice. Section VI-D shows why that choice fails on coordinated campaigns, and what replaces it."),
  P("***D. Training Graph Recommenders on Their Own Edges.*** When a recommender is trained to predict an edge that is also present as a message-passing edge, the model can read the label off the graph. Link-prediction practice handles this by separating message-passing edges from supervision edges (for example the disjoint split in PyTorch Geometric's link splitter), and DropEdge [10] randomly removes edges during training as a regulariser. We do not claim the idea; Section VI-B reports how large the effect is for an HGT recommender, and that the published-style recipe without it is a poor baseline."),
  P("***E. Time-Aware and Explainable Recommendation.*** Weighting older interactions less is a long-standing idea in collaborative filtering [11]. For explanation we follow one principle from explainable-AI work: a justification must be traceable to evidence the model actually retrieved, not generated as a plausible afterthought."),
];

const dataSection = (F) => [
  P("We evaluate on Amazon Reviews 2023 [6], released by the McAuley Lab at UC San Diego, used as downloaded: the raw files are never edited and every transformation is disclosed in Section IV-A. Data collection works from CSV. The raw JSON review and metadata files are converted once to flat CSV (list and dictionary cells are stored as JSON text and decoded on read), and every later stage reads the CSV. The dataset ships a three-tier profile so that development runs, CI checks and the reported experiments share one schema adapter. Table I lists the tiers; the sizes are measured Content-Length values, not estimates."),
  L.caption("**TABLE I** — Dataset tier configuration (measured, not estimated).", { after: 40 }),
  L.table(["Tier", "Category", "Reviews", "Metadata", "Role"], [
    ["smoke", "All_Beauty", "0.30 GB", "0.20 GB", "CI and wiring checks"],
    ["dev (used)", "Video_Games", "2.50 GB", "0.41 GB", "Main results"],
    ["dev (second)", "Musical_Instruments", "1.45 GB", "0.59 GB", "Replication, Section VI-K"],
    ["full", "Electronics", "21.06 GB", "4.89 GB", "Streamed only"],
  ], [900, 1500, 700, 700, 1100], { align: [A.LEFT, A.LEFT, A.RIGHT, A.RIGHT, A.LEFT] }),
  P("Every main experiment runs on the dev (Video_Games) tier, and Section VI-K repeats the pipeline on the same tier of a second category, Musical_Instruments. Electronics needs 21.06 GB of reviews and 4.89 GB of metadata against 30 GB of free disk on the development machine, so it was demoted to a streamed tier; this is a real constraint that shaped what was measured, not a methodological choice.", { before: 80 }),
  P("***A. Problem Formulation.*** Given a chronologically ordered set of user–item interactions, each optionally carrying a rating, free-text review, timestamp, helpful-vote count and verified-purchase flag, the task has three parts: produce a ranked top-K list per user that maximises ranking accuracy on a strictly future split; derive, without fraud labels, a per-interaction trust weight that down-weights unreliable evidence during training; and attach to every recommendation a retrieved explanation, a counterfactual statement and a confidence score. All three are evaluated in Section VI."),
];

const method = (F) => {
  const T = F.tuned;
  return [
    P("DyTrustRec runs as eighteen modules in five stages: ingestion and a leakage-safe split, feature engineering, trust-aware graph construction, an HGT encoder trained with edge masking, and an explainability layer. Fig. 1 shows the pipeline; Sections IV-A to IV-E take the stages in turn."),
    P("***A. Data Ingestion, Cleaning and Leakage-Safe Split.*** A schema adapter maps source field names onto a canonical schema; a declared field that is absent from the source is marked absent, not invented, which is why the graph has five node types rather than the six first planned (Amazon Reviews 2023 has no seller field). Cleaning separates two kinds of bad record. Records that cannot be interpreted (out-of-range rating, impossible timestamp, missing key) are removed. Records that are merely suspicious (near-duplicate text across items, unusual length, bursts inside a sixty-second window) are flagged with a reason string and kept, because deleting them would leave the trust detectors nothing to find."),
    P("On the dev tier this takes 262,547 raw rows to 144,178 interactions over 17,223 users and 7,692 items (54.9% retained) after removing 5,050 exact duplicates, collapsing 2,476 repeat interactions and applying a five-core filter. A strict chronological 80/10/10 split follows (115,342 / 14,418 / 14,418 interactions). Six assertions in the test suite check that the training graph holds only training-period edges, that every leakage-sensitive statistic is fitted on training data alone, that the recency reference is the maximum training timestamp and never wall-clock time, and that negative sampling excludes positives from every split. The strictness has a price: 42.3% of test rows involve a user and 59.7% an item never seen in training, so only 1,862 users are evaluable, and every metric in Section VI is computed over exactly that set."),
    P("***B. Features: Sentiment, Semantics and Fusion.*** The semantic branch concatenates title and body, encodes them with SBERT [2] (all-MiniLM-L6-v2), mean-pools and L2-normalises to a 384-dimension vector, and caches it under a key built from the model, pooling settings and text (encoding all 115,342 training reviews takes 394 s, once). The sentiment branch uses nlptown/bert-base-multilingual-uncased-sentiment, a BERT model fine-tuned on product reviews to predict a one-to-five star rating, remapped onto pos/neg/neu/compound (compound = (E[star] − 3)/2). It runs frozen, so it adds no training-data leakage. The semantic vector, the sentiment compound and four structured features (log review length, log helpful votes, verified-purchase flag, and a rating centred on the item's training-only mean) plus a recency weight form a 390-dimension review vector. The learned Semantic-Behavioural Fusion layer (LayerNorm, 390→256, GELU, dropout, 256→128, LayerNorm) compresses it; a separate ablation arm concatenates raw instead, so that \"learned fusion beats concatenation\" is tested and not assumed."),
    P(`***C. Trust-Aware Graph, Trust and Recency Weights.*** The graph has five node types (user 15,704, product 6,619, review 115,342, category 37, brand 778; brand is a proxy derived from the storefront field) and five relation types, each added in both directions: ${F.graph.nodes} nodes and ${F.graph.edges} edges.`),
    P("**Trust.** The original design derived trust from CoLA [3] on a user–product projection, mapped by τ = 1 − rank-norm(score), clamped to [0.05, 1]. The production path now uses a behavioural detector with three label-free indicators, each rank-normalised and averaged with equal weight: the share of a user's reviews whose text other accounts also posted (campaign templates), the share that repeat the user's own text, and the most reviews posted inside any 24-hour window. Nothing is tuned. Users with fewer than three interactions receive the median score, which means no evidence, not clean. A fourth indicator, distance from the item's mean rating, was tried and removed because on the synthetic benchmark it pointed the wrong way (AUC 0.19 to 0.34). The same rank-and-clamp mapping converts the score to trust, and the floor matters: a weight of exactly zero would silently delete an interaction from training."),
    P(`**Recency.** recency = exp(−λ·age), floored at 0.01, with age in years from the maximum training timestamp. The decay rate λ is selected on the validation split (Section VI-A; selected value ${T.lambda}).`),
    P("**How the weights act.** The weights are not edge weights. HGTConv cannot consume them, so an edge weight stored on the graph has no effect on the model; the first version of this project did exactly that, which made its trust and recency arms identical to the unweighted model (Section VI-C). Here the combined weight w = τ^α · recency^β scales each interaction's term in the training objective, rescaled to mean 1 so that weighting changes where the gradient goes and not its size."),
    P(`***D. HGT Encoder and Training.*** Node types arrive with different dimensionality (user 20-d, product 18-d, review 128-d fused or 390-d concatenated; category and brand carry only a learned embedding), so a type-specific linear layer maps each into 128 dimensions before two relation-aware attention layers (four heads, 128 hidden channels, dropout ${T.dropout}). Scoring is a dot product of the final user and product embeddings. Four training details matter more than the architecture and are measured in Section VI.`),
    ...bullets([
      `**Edge masking.** The interaction being scored is also a message-passing edge, so an unmasked HGT can read the answer off the graph. Each epoch a random ${T.hiddenPct}% of interaction rows are hidden from message passing (all edge types that encode the same row, forward and reverse, share one mask), and those rows are the supervision targets. Evaluation uses the full graph.`,
      "**Validation early stopping.** NDCG@10 on the validation split is measured every five epochs; the best weights are restored and training stops after eight measurements without improvement. Every model in the comparison, baselines included, is stopped this way.",
      `**Weighted BPR.** The objective is Bayesian Personalised Ranking [4] with one uniform negative per positive, AdamW, learning rate ${T.lr}, weight decay 10^−4^.`,
      "**Seed ensemble.** An ensemble averages the per-user z-scored scores of independently trained runs. Scores are averaged, not embeddings: two runs place users and items in unrelated coordinate systems.",
    ], { size: 19 }),
    P("The encoder trains full-graph, one optimiser step per epoch. On Apple's Metal backend the fused segment_matmul kernel in PyTorch Geometric has no implementation, so it is disabled for that backend; the rest of the attention computation is untouched."),
    P("***E. Explainability Suite.*** Three modules sit on the encoder. The explanation module retrieves evidence from six sources (shared category, shared brand, similar high-trust users, recent history, semantic similarity, review sentiment) and fills a template only when a source returns something; with none it says so, a behaviour pinned by a test that checks an unknown user gets no evidence. The counterfactual module bisects over one perturbable factor at a time (category affinity, brand affinity, recency weight, trust weight, semantic similarity) and reports the change needed to enter the top-K, or an explicit INFEASIBLE. The confidence module blends predictive stability (0.5), evidence volume (0.3) and evidence trust (0.2), halved for cold-start users. Stability is the normalised disagreement between ensemble members, the same normalisation used for Monte Carlo dropout."),
  ];
};

const setup = (F) => [
  P("***A. Hardware and Software.*** All experiments ran on one Apple M3 Pro (12 cores: 6 performance, 6 efficiency; 18 GB unified memory) with no discrete GPU, using Metal Performance Shaders, PyTorch 2.13.0 and PyTorch Geometric 2.8.0. Two practical facts shaped the protocol: two HGT trainings on the same GPU stall each other, and CPU-heavy work alongside one slows it badly, so runs were executed one at a time."),
  P("***B. Baselines and Ablation Grid.*** Five baselines are trained on the same split and scored by the same evaluator: global popularity; item-based kNN (cosine); BPR matrix factorisation with an item bias; LightGCN; and SASRec [12], the standard sequential model, which reads each user's items in time order with causal self-attention and knows nothing about reviews, trust or the graph. Each baseline's hyper-parameters were searched on the validation split (kNN neighbours; MF dimension, learning rate and weight decay; LightGCN dimension, depth, learning rate and weight decay; SASRec dimension, dropout, learning rate and sequence length) and each is stopped by validation NDCG@10, exactly like the HGT. The first version of this project gave the baselines no such search, and its LightGCN scored below popularity. Table II defines the nine HGT arms. Arms A to G add one component at a time; arm H is arm B with edge masking switched off, and arm I is arm E with a cosine learning-rate decay over a validation-tuned epoch budget (early stopping off, best-validation checkpoint restored)."),
  L.caption("**TABLE II** — HGT ablation arms. All share one training procedure except H (no masking) and I (cosine decay).", { after: 40 }),
  L.table(["Arm", "Name", "SBERT", "Fusion", "Trust", "Recency"], [
    ["A", "hgt_only", "–", "–", "–", "–"],
    ["B", "hgt_sbert", "✓", "–", "–", "–"],
    ["C", "hgt_sbert_trust", "✓", "–", "behavioural", "–"],
    ["D", "hgt_sbert_recency", "✓", "–", "–", "✓"],
    ["E", "hgt_sbert_trust_recency", "✓", "–", "behavioural", "✓"],
    ["F", "dytrustrec_full", "✓", "✓", "behavioural", "✓"],
    ["G", "dytrustrec_cola_trust", "✓", "✓", "CoLA", "✓"],
    ["H", "hgt_sbert_unmasked", "✓", "–", "–", "–"],
    ["I", "dytrustrec_cosine", "✓", "–", "behavioural", "✓"],
  ], [340, 1700, 640, 640, 900, 700], { size: 14, align: [A.LEFT, A.LEFT, A.CENTER, A.CENTER, A.CENTER, A.CENTER] }),
  P("***C. Protocol and Metrics.*** Every model scores the full catalogue for every evaluable user with training positives masked; users with no held-out item are excluded and counted, not scored as zero. Precision, Recall, NDCG, MAP, MRR and Hit Rate are computed at K ∈ {5, 10, 20} with binary relevance; coverage, diversity and novelty are computed over the post-cleaning catalogue. Hyper-parameters were chosen on the validation split only, and the test split is scored once per run, at the weights that validated best. Each reported number is a mean ± standard deviation over independent seeds (five for the baselines and for arms B and F, three for the other arms), each with its own initialisation, mask stream and negative sampler. Differences between models are tested with a paired bootstrap over users (4,000 draws) on per-user NDCG@10 averaged across seeds.", { before: 80 }),
];

module.exports = { relatedWork, dataSection, method, setup };
